function mint(address to, uint256 amount) public onlyOwner { _mint(to, amount); }
function burn(uint256 amount) public { _burn(msg.sender, amount); }
function transfer(address to, uint256 amount) public returns (bool) { _transfer(msg.sender, to, amount); return true; }
function blacklist(address account) public onlyOwner { blacklisted[account] = true; }
